def get_icon(icon_key: str, color: str = None, width: str = None, height: str = None) -> str:
    """Get SVG icon with optional color and size styling."""
    svg = ICONS.get(icon_key, ICONS["dashboard"])
    
    if color:
        svg = svg.replace('stroke="currentColor"', f'stroke="{color}"')
    
    if width or height:
        # Replace width/height attributes
        if width:
            svg = svg.replace('width="24"', f'width="{width}"').replace('width="20"', f'width="{width}"').replace('width="18"', f'width="{width}"')
        if height:
            svg = svg.replace('height="24"', f'height="{height}"').replace('height="20"', f'height="{height}"').replace('height="18"', f'height="{height}"')
    
    return svg